code:
databaseChangeLog:
  - changeSet:
      id: {{change_id}}
      author: {{author}}
      changes:
        - addColumn:
            tableName: {{table_name}}
            columns:
              - column:
                  name: {{col_name}}
                  type: TEXT
      rollback:
        - dropColumn:
            tableName: {{table_name}}
            columnName: {{col_name}}
